import{_ as t,a0 as o,w as r,s as c,ao as l,I as p,x as n,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"Chrony：一个类 Unix 系统上 NTP 客户端和服务器替代品 | LCTT x X-CMD","titleTemplate":false,"description":"Chrony：一个类 Unix 系统上 NTP 客户端和服务器替代品 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Chrony：一个类 Unix 系统上 NTP 客户端和服务器替代品 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Chrony：一个类 Unix 系统上 NTP 客户端和服务器替代品 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181017 Chrony - An Alternative NTP Client And Server For Unix-like Systems","title":"Chrony：一个类 Unix 系统上 NTP 客户端和服务器替代品","tag":"201811","desc":""},"relativePath":"201811/20181017 Chrony - An Alternative NTP Client And Server For Unix-like Systems.md","filePath":"[post].md"}'),d={name:"201811/20181017 Chrony - An Alternative NTP Client And Server For Unix-like Systems.md"};function h(u,s,g,k,b,y){const a=o("Link");return r(),c("div",null,[s[18]||(s[18]=l(`<h1 id="chrony-一个类-unix-系统上-ntp-客户端和服务器替代品" tabindex="-1">Chrony：一个类 Unix 系统上 NTP 客户端和服务器替代品 <a class="header-anchor" href="#chrony-一个类-unix-系统上-ntp-客户端和服务器替代品" aria-label="Permalink to “Chrony：一个类 Unix 系统上 NTP 客户端和服务器替代品”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/chrony-1-720x340.jpeg" alt=""></p><p>在这个教程中，我们会讨论如何安装和配置 <strong>Chrony</strong>，一个类 Unix 系统上 NTP 客户端和服务器的替代品。Chrony 可以更快的同步系统时钟，具有更好的时钟准确度，并且它对于那些不是一直在线的系统很有帮助。Chrony 是自由开源的，并且支持 GNU/Linux 和 BSD 衍生版（比如 FreeBSD、NetBSD）、macOS 和 Solaris 等。</p><h3 id="安装-chrony" tabindex="-1">安装 Chrony <a class="header-anchor" href="#安装-chrony" aria-label="Permalink to “安装 Chrony”">​</a></h3><p>Chrony 可以从大多数 Linux 发行版的默认软件库中获得。如果你使用的是 Arch Linux，运行下面的命令来安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S chrony</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install chrony</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install chrony</span></span></code></pre></div><p>当安装完成后，如果之前没有启动过的话需启动 <code>chronyd.service</code> 守护进程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl start chronyd.service</span></span></code></pre></div><p>使用下面的命令让它每次重启系统后自动运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable chronyd.service</span></span></code></pre></div><p>为了确认 <code>chronyd.service</code> 已经启动，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status chronyd.service</span></span></code></pre></div><p>如果一切正常，你将看到类似下面的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>● chrony.service - chrony, an NTP client/server</span></span>
<span class="line"><span>Loaded: loaded (/lib/systemd/system/chrony.service; enabled; vendor preset: ena</span></span>
<span class="line"><span>Active: active (running) since Wed 2018-10-17 10:34:53 UTC; 3min 15s ago</span></span>
<span class="line"><span>Docs: man:chronyd(8)</span></span>
<span class="line"><span>man:chronyc(1)</span></span>
<span class="line"><span>man:chrony.conf(5)</span></span>
<span class="line"><span>Main PID: 2482 (chronyd)</span></span>
<span class="line"><span>Tasks: 1 (limit: 2320)</span></span>
<span class="line"><span>CGroup: /system.slice/chrony.service</span></span>
<span class="line"><span>└─2482 /usr/sbin/chronyd</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Oct 17 10:34:53 ubuntuserver systemd[1]: Starting chrony, an NTP client/server...</span></span>
<span class="line"><span>Oct 17 10:34:53 ubuntuserver chronyd[2482]: chronyd version 3.2 starting (+CMDMON</span></span>
<span class="line"><span>Oct 17 10:34:53 ubuntuserver chronyd[2482]: Initial frequency -268.088 ppm</span></span>
<span class="line"><span>Oct 17 10:34:53 ubuntuserver systemd[1]: Started chrony, an NTP client/server.</span></span>
<span class="line"><span>Oct 17 10:35:03 ubuntuserver chronyd[2482]: Selected source 85.25.84.166</span></span>
<span class="line"><span>Oct 17 10:35:03 ubuntuserver chronyd[2482]: Source 85.25.84.166 replaced with 2403</span></span>
<span class="line"><span>Oct 17 10:35:03 ubuntuserver chronyd[2482]: Selected source 91.189.89.199</span></span>
<span class="line"><span>Oct 17 10:35:06 ubuntuserver chronyd[2482]: Selected source 106.10.186.200</span></span></code></pre></div><p>可以看到，Chrony 服务已经启动并且正在工作！</p><h3 id="配置-chrony" tabindex="-1">配置 Chrony <a class="header-anchor" href="#配置-chrony" aria-label="Permalink to “配置 Chrony”">​</a></h3><p>NTP 客户端需要知道它要连接到哪个 NTP 服务器来获取当前时间。我们可以直接在该 NTP 配置文件中的 <code>server</code> 或者 <code>pool</code> 项指定 NTP 服务器。通常，默认的配置文件位于 <code>/etc/chrony/chrony.conf</code> 或者 <code>/etc/chrony.conf</code>，取决于 Linux 发行版版本。为了更可靠的同步时间，建议指定至少三个服务器。</p><p>下面几行是我的 Ubuntu 18.04 LTS 服务器上的一个示例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[...]</span></span>
<span class="line"><span># About using servers from the NTP Pool Project in general see (LP: #104525).</span></span>
<span class="line"><span># Approved by Ubuntu Technical Board on 2011-02-08.</span></span>
<span class="line"><span># See http://www.pool.ntp.org/join.html for more information.</span></span>
<span class="line"><span>pool ntp.ubuntu.com iburst maxsources 4</span></span>
<span class="line"><span>pool 0.ubuntu.pool.ntp.org iburst maxsources 1</span></span>
<span class="line"><span>pool 1.ubuntu.pool.ntp.org iburst maxsources 1</span></span>
<span class="line"><span>pool 2.ubuntu.pool.ntp.org iburst maxsources 2</span></span>
<span class="line"><span>[...]</span></span></code></pre></div>`,23)),p("p",null,[s[1]||(s[1]=n("从上面的输出中你可以看到，",-1)),e(a,{href:"https://www.ntppool.org/en/"},{default:i(()=>[...s[0]||(s[0]=[n("NTP 服务器池项目",-1)])]),_:1}),s[2]||(s[2]=n(" 已经被设置成为了默认的时间服务器。对于那些好奇的人，NTP 服务器池项目是一个时间服务器集群，用来为全世界千万个客户端提供 NTP 服务。它是 Ubuntu 以及其他主流 Linux 发行版的默认时间服务器。",-1))]),s[19]||(s[19]=l(`<p>在这里，</p><ul><li><code>iburst</code> 选项用来加速初始的同步过程</li><li><code>maxsources</code> 代表 NTP 源的最大数量</li></ul><p>请确保你选择的 NTP 服务器是同步的、稳定的、离你的位置较近的，以便使用这些 NTP 源来提升时间准确度。</p><h3 id="在命令行中管理-chronyd" tabindex="-1">在命令行中管理 Chronyd <a class="header-anchor" href="#在命令行中管理-chronyd" aria-label="Permalink to “在命令行中管理 Chronyd”">​</a></h3><p>chrony 有一个命令行工具叫做 <code>chronyc</code> 用来控制和监控 chrony 守护进程（<code>chronyd</code>）。</p><p>为了检查是否 chrony 已经同步，我们可以使用下面展示的 <code>tracking</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chronyc tracking</span></span>
<span class="line"><span>Reference ID : 6A0ABAC8 (t1.time.sg3.yahoo.com)</span></span>
<span class="line"><span>Stratum : 3</span></span>
<span class="line"><span>Ref time (UTC) : Wed Oct 17 11:48:51 2018</span></span>
<span class="line"><span>System time : 0.000984587 seconds slow of NTP time</span></span>
<span class="line"><span>Last offset : -0.000912981 seconds</span></span>
<span class="line"><span>RMS offset : 0.007983995 seconds</span></span>
<span class="line"><span>Frequency : 23.704 ppm slow</span></span>
<span class="line"><span>Residual freq : +0.006 ppm</span></span>
<span class="line"><span>Skew : 1.734 ppm</span></span>
<span class="line"><span>Root delay : 0.089718960 seconds</span></span>
<span class="line"><span>Root dispersion : 0.008760406 seconds</span></span>
<span class="line"><span>Update interval : 515.1 seconds</span></span>
<span class="line"><span>Leap status : Normal</span></span></code></pre></div><p>我们可以使用命令确认现在 chrony 使用的时间源：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chronyc sources</span></span>
<span class="line"><span>210 Number of sources = 8</span></span>
<span class="line"><span>MS Name/IP address Stratum Poll Reach LastRx Last sample</span></span>
<span class="line"><span>===============================================================================</span></span>
<span class="line"><span>^- chilipepper.canonical.com 2 10 377 296 +102ms[ +104ms] +/- 279ms</span></span>
<span class="line"><span>^- golem.canonical.com 2 10 377 302 +105ms[ +107ms] +/- 290ms</span></span>
<span class="line"><span>^+ pugot.canonical.com 2 10 377 297 +36ms[ +38ms] +/- 238ms</span></span>
<span class="line"><span>^- alphyn.canonical.com 2 10 377 279 -43ms[ -42ms] +/- 238ms</span></span>
<span class="line"><span>^- dadns.cdnetworks.co.kr 2 10 377 1070 +40ms[ +42ms] +/- 314ms</span></span>
<span class="line"><span>^* t1.time.sg3.yahoo.com 2 10 377 169 -13ms[ -11ms] +/- 80ms</span></span>
<span class="line"><span>^+ sin1.m-d.net 2 10 275 567 -9633us[-7826us] +/- 115ms</span></span>
<span class="line"><span>^- ns2.pulsation.fr 2 10 377 311 -75ms[ -73ms] +/- 250ms</span></span></code></pre></div><p><code>chronyc</code> 工具可以对每个源进行统计，比如使用 <code>sourcestats</code> 命令获得漂移速率和进行偏移估计。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chronyc sourcestats</span></span>
<span class="line"><span>210 Number of sources = 8</span></span>
<span class="line"><span>Name/IP Address NP NR Span Frequency Freq Skew Offset Std Dev</span></span>
<span class="line"><span>==============================================================================</span></span>
<span class="line"><span>chilipepper.canonical.com 32 16 89m +6.293 14.345 +30ms 24ms</span></span>
<span class="line"><span>golem.canonical.com 32 17 89m +0.312 18.887 +20ms 33ms</span></span>
<span class="line"><span>pugot.canonical.com 32 18 89m +0.281 11.237 +3307us 23ms</span></span>
<span class="line"><span>alphyn.canonical.com 31 20 88m -4.087 8.910 -58ms 17ms</span></span>
<span class="line"><span>dadns.cdnetworks.co.kr 29 16 76m -1.094 9.895 -83ms 14ms</span></span>
<span class="line"><span>t1.time.sg3.yahoo.com 32 16 91m +0.153 1.952 +2835us 4044us</span></span>
<span class="line"><span>sin1.m-d.net 29 13 83m +0.049 6.060 -8466us 9940us</span></span>
<span class="line"><span>ns2.pulsation.fr 32 17 88m +0.784 9.834 -62ms 22ms</span></span></code></pre></div><p>如果你的系统没有连接到互联网，你需要告知 Chrony 系统没有连接到 互联网。为了这样做，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chronyc offline</span></span>
<span class="line"><span>[sudo] password for sk:</span></span>
<span class="line"><span>200 OK</span></span></code></pre></div><p>为了确认你的 NTP 源的状态，只需要运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chronyc activity</span></span>
<span class="line"><span>200 OK</span></span>
<span class="line"><span>0 sources online</span></span>
<span class="line"><span>8 sources offline</span></span>
<span class="line"><span>0 sources doing burst (return to online)</span></span>
<span class="line"><span>0 sources doing burst (return to offline)</span></span>
<span class="line"><span>0 sources with unknown address</span></span></code></pre></div><p>可以看到，我的所有源此时都是离线状态。</p><p>一旦你连接到互联网，只需要使用命令告知 Chrony 你的系统已经回到在线状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chronyc online</span></span>
<span class="line"><span>200 OK</span></span></code></pre></div><p>为了查看 NTP 源的状态，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chronyc activity</span></span>
<span class="line"><span>200 OK</span></span>
<span class="line"><span>8 sources online</span></span>
<span class="line"><span>0 sources offline</span></span>
<span class="line"><span>0 sources doing burst (return to online)</span></span>
<span class="line"><span>0 sources doing burst (return to offline)</span></span>
<span class="line"><span>0 sources with unknown address</span></span></code></pre></div><p>所有选项和参数的详细解释，请参考其帮助手册。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man chronyc</span></span>
<span class="line"><span>$ man chronyd</span></span></code></pre></div><p>这就是文章的所有内容。希望对你有所帮助。在随后的教程中，我们会看到如何使用 Chrony 启动一个本地的 NTP 服务器并且配置客户端来使用这个服务器同步时间。</p><p>保持关注！</p><hr>`,25)),p("p",null,[s[4]||(s[4]=n("via: ",-1)),e(a,{href:"https://www.ostechnix.com/chrony-an-alternative-ntp-client-and-server-for-unix-like-systems/"},{default:i(()=>[...s[3]||(s[3]=[n("https://www.ostechnix.com/chrony-an-alternative-ntp-client-and-server-for-unix-like-systems/",-1)])]),_:1})]),p("p",null,[s[9]||(s[9]=n("作者：",-1)),e(a,{href:"https://www.ostechnix.com/author/sk/"},{default:i(()=>[...s[5]||(s[5]=[n("SK",-1)])]),_:1}),s[10]||(s[10]=n(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[n("lujun9972",-1)])]),_:1}),s[11]||(s[11]=n(" 译者：",-1)),e(a,{href:"https://github.com/zianglei"},{default:i(()=>[...s[7]||(s[7]=[n("zianglei",-1)])]),_:1}),s[12]||(s[12]=n(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[n("Linux中国",-1)])]),_:1}),s[17]||(s[17]=n(" 荣誉推出",-1))])])}const v=t(d,[["render",h]]);export{C as __pageData,v as default};
